from lib import *
S = SS('w28')
steps = [
    step("UDP 头只有 8 字节:源端口、目的端口、长度、校验和各 2 字节。lo0 上抓到三个数据报:载荷 5 字节的头是 df01 c407 000d fe20——源端口 57089(正是发送套接字的端口)、目的端口 50183、长度 13 = 8 + 5、校验和字段 0xfe20;载荷为 0 字节的数据报长度 8,IP 总长 28,是合法的,接收方会收到一个空的数据报;载荷 1000 字节的长度 1008,IP 总长 1028 = 20 + 1008。lo0 上的校验和字段是还没算完的占位值(第 17 篇已经看到,本机内的包校验和被卸载)。接收方三次 recvfrom 得到的长度是 5、0、1000——每次 recvfrom 对应发送方的一次 sendto。", t=tl(S(1)), mark=lidx(S(1), '头 df01 c407 000d', '载荷为 0 字节'), done=lidx(S(1), '头 df01 c407 0008', '头 df01 c407 03f0', '接收方三次 recvfrom'), b=bars([['IP 头', 20, '20 字节'], ['UDP 头', 8, '8 字节'], ['TCP 头(无选项)', 20, '20 字节']], 20, mark=[1], done=[0, 2]), kv=KV([['UDP 头', '源端口 · 目的端口 · 长度 · 校验和,各 2 字节'], ['长度', '8 + 载荷(含 UDP 头本身)'], ['0 字节载荷', '合法,长度 8'], ['每次 sendto', '对应接收方一次 recvfrom']], ['长度'])),
    step("UDP 保留报文边界:连发 10、20、30 字节三个数据报,接收方 3 次 recvfrom 分别拿到 10、20、30 字节。如果接收方的缓冲区太小(5 字节收一个 20 字节的数据报),recvmsg 只返回 5 字节,MSG_TRUNC 标志置位,再收一次什么也没有——剩下的 15 字节被丢掉了。对比 TCP:同样发 10、20、30 字节,接收方一次 recv 就拿到 60 字节,三次发送被合并成一个字节流,边界没有了——TCP 的应用必须自己在字节流里划分消息。", t=tl(S(2)), mark=lidx(S(2), '再发一个 20 字节', 'TCP 同样发'), done=lidx(S(2), '连发 10、20、30'), b=bars([['UDP · 第 1 次 recvfrom', 10, '10'], ['UDP · 第 2 次', 20, '20'], ['UDP · 第 3 次', 30, '30'], ['TCP · 一次 recv', 60, '60']], 60, mark=[3], done=[0, 1, 2]), kv=KV([['UDP', '每次 recvfrom 一个完整数据报'], ['缓冲区太小', '多出的部分丢掉(MSG_TRUNC)'], ['TCP', '字节流,三次发送合并成 60 字节']], ['缓冲区太小'])),
    step("“无连接”的实际含义:一次 4 字节的请求加应答,UDP 一共 2 个包(64 字节的 IP 包);TCP 包含建立连接、请求、应答和关闭共 12 个包(656 字节)。没有延迟时 UDP 一问一答 70 µs、TCP(含建立连接)207 µs。用 netlab 给回环加单向 20 ms(往返 40 ms)后:UDP 一问一答 40.7 ms,约 1 个往返;TCP 含建立连接 81.2 ms,约 2 个往返——先三次握手一个往返,再请求应答一个往返。UDP 没有握手,第一个包就可以带数据;代价是没有可靠性,也没有连接状态可以让对方拒绝。", t=tl(S(3)), mark=lidx(S(3), '单向 20 ms', '一次 4 字节'), done=lidx(S(3), '没有延迟'), b=bars([['UDP · 往返 40 ms 时一问一答', 40.7, '40.7 ms'], ['TCP · 含建立连接', 81.2, '81.2 ms']], 81.2, mark=[1], done=[0]), kv=KV([['UDP', '2 个包,约 1 个往返'], ['TCP', '12 个包,约 2 个往返'], ['无延迟', 'UDP 70 µs / TCP 207 µs']], ['UDP'])),
    step("端口:系统的临时端口范围是 49152 到 65535。创建 1000 个不指定端口的 UDP 套接字,得到 1000 个互不相同的端口(范围 49164~65496),相邻两个恰好 +1 的有 0 个——端口是随机分配的,不是顺序递增。同一个端口的重复绑定:第一个套接字绑 0.0.0.0:50625;再绑 0.0.0.0 同一端口失败(Address already in use),再绑 127.0.0.1 同一端口也失败,设了 SO_REUSEADDR 后再绑 0.0.0.0 仍失败,设了 SO_REUSEPORT(两边都设)才成功。", t=tl(S(4)), mark=lidx(S(4), '第一个套接字绑 0.0.0.0', '1000 个不指定端口'), done=lidx(S(4), 'net.inet.ip.portrange.first'), kv=KV([['临时端口', '49152 ~ 65535'], ['1000 个套接字', '端口互不相同,不是顺序'], ['重复绑定', '默认失败;SO_REUSEPORT 才可以'], ['SO_REUSEADDR', '对 UDP 绑同一 0.0.0.0 端口没帮助']], ['SO_REUSEADDR'])),
    step("数据报大小上限:协议上限是 65507 字节(65535 − 20 − 8)。系统还有自己的限制:net.inet.udp.maxdgram = 9216,net.inet.udp.recvspace = 786896,net.inet.udp.checksum = 1。默认发送缓冲区下 9216 字节发送成功,9217、65507、65508 字节都是 Message too long;把 SO_SNDBUF 调到 1 MiB 后 9217 和 65507 字节也成功,65508 字节仍是 Message too long——这时才是协议本身的上限。", t=tl(S(5)), mark=lidx(S(5), '默认发送缓冲区', '调大 SO_SNDBUF'), done=lidx(S(5), 'net.inet.udp.maxdgram', 'net.inet.udp.recvspace', 'net.inet.udp.checksum'), b=bars([['默认能发的最大', 9216, '9216 字节'], ['调大 SO_SNDBUF 后', 65507, '65507 字节'], ['协议上限 65535−20−8', 65507, '65507 字节']], 65507, mark=[1], done=[0, 2]), kv=KV([['net.inet.udp.maxdgram', '9216(默认发送上限)'], ['调大 SO_SNDBUF', '最大到 65507'], ['65508', '任何情况下都是 Message too long']], ['65508'])),
]
A = mkartw('w28', 28, '网络协议,UDP,UDP头,报文边界,端口,无连接,真实验证,动画演示',
    '解码 lo0 上的 UDP 头(8 字节,长度 = 8 + 载荷);UDP 保留报文边界、缓冲区太小会截断,TCP 把三次发送合并成 60 字节;一问一答 UDP 2 个包约 1 个往返、TCP 12 个包约 2 个往返;临时端口随机分配;数据报上限 65507,默认只能发 9216。',
    'UDP 头只有 8 个字节,它到底少了什么?“无连接”具体省掉了多少包和多少往返?报文边界是怎么保留的,缓冲区太小会发生什么?这篇在 lo0 上解码真实的 UDP 头,并用 netlab 加延迟实测 UDP 与 TCP 一问一答的差别。',
    [('8 字节', 'UDP 头大小:源端口、目的端口、长度、校验和各 2 字节'), ('1 个往返 对 2 个往返', '往返 40 ms 时,UDP 一问一答 40.7 ms,TCP 含建立连接 81.2 ms'), ('65507', 'UDP 数据报的最大载荷:65535 − 20 − 8;macOS 默认只允许发 9216,调大 SO_SNDBUF 才行')],
    [('UDP 头', '<p>只有源端口、目的端口、长度、校验和,各 2 字节。长度含 UDP 头本身,所以 0 字节载荷的数据报长度是 8,也是合法的。</p>'),
     ('报文边界', '<p>每次 sendto 对应接收方的一次 recvfrom;缓冲区小于数据报时多出的部分被丢掉(MSG_TRUNC)。TCP 是字节流,会把几次发送合并。</p>'),
     ('无连接', '<p>一问一答 UDP 只要 2 个包、1 个往返;TCP 要 12 个包、2 个往返。代价是没有可靠性,也没有连接状态。</p>'),
     ('端口', '<p>临时端口 49152~65535 随机分配(1000 个套接字没有一对连号);同一端口重复绑定默认失败,SO_REUSEPORT 才可以。</p>'),
     ('大小上限', '<p>数据报上限 65507,但系统默认只允许发 9216 字节,调大发送缓冲区才能发更大的。</p>')],
    steps,
    [ENV_W + '。第一、二、四、五节在回环上做(lo0 上的 UDP 校验和字段是占位值,见第 17 篇);第三节的延迟由 netlab 在 lo0 的 9400~9499 端口上注入(每个方向 20 ms);时间数字为中位数,无延迟时只看量级',
     '没有验证:真实网络上(en0 以外)的 UDP 往返;UDP-Lite(部分校验和);UDP 在 IPv6 里校验和不能省略的规则;SO_REUSEPORT 在多个套接字间如何分流数据报(见广播与组播两篇);不同 macOS 版本的 maxdgram 默认值'],
    'UDP 头部')
